package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoImmediateControlsReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun perform(a:HonorableVideoEditorActivity,action:()->Unit)=call(a,"performImmediateVideoAction",action)as Boolean
 private fun block(a:HonorableVideoEditorActivity,flag:String){when(flag){"pause"->set(a,"workspaceActive",false);"saving"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);"draft"->set(a,"draftBusy",true);"import"->set(a,"importing",true);"range"->set(a,"pendingRange",0L to 1000L);"bytes"->set(a,"recoveryBytes",byteArrayOf(1));"blocked"->set(a,"recoveryBlocked",true);"checking"->set(a,"recoveryChecking",true);"project"->set(a,"project",null);"source"->set(a,"source",null);else->set(a,"selectedClip",1)}}
 @Test fun admittedImmediateEditRunsOnceWithOneUndoAndGenerationAdvance(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val music=p.soundtrack;var calls=0;assertTrue(perform(a){calls++;p.setVolume(0,.5f)});assertEquals(1,calls);assertEquals(before[0].copy(volume=.5f),p.segments[0]);assertSame(music,p.soundtrack);assertEquals(1L,get(a,"captionReviewGeneration"));assertTrue(p.undo());assertEquals(before,p.segments);assertFalse(p.canUndo)}
 @Test fun blockedForegroundRecoveryBusySourceAndSelectionNeverReachSideEffects(){for(flag in listOf("pause","saving","analysis","draft","import","range","bytes","blocked","checking","project","source","selection")){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;block(a,flag);assertFalse(flag,perform(a){fail("mutated while $flag")});assertSame(before,p.segments);assertFalse(p.canUndo);assertEquals(0L,get(a,"captionReviewGeneration"))}}
 @Test fun oldActionLeasesAreClosedBeforeAcceptedMutation(){val a=activity();val moment=VideoActionReview();moment.open(Any());val look=VideoLookReview();look.open(Any());val p=get(a,"project")as VideoEditProject;val batch=VideoBatchReview(p.segments,p.soundtrack);batch.open(Any());set(a,"momentReviewRequest",moment);set(a,"lookReviewRequest",look);set(a,"batchReviewRequest",batch);set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());assertTrue(perform(a){assertTrue(moment.isClosed);assertTrue(look.isClosed);assertTrue(batch.isClosed);assertNull(get(a,"momentReviewRequest"));assertNull(get(a,"lookReviewRequest"));assertNull(get(a,"batchReviewRequest"));assertEquals(1L,get(a,"captionReviewGeneration"));p.setVolume(0,.5f)});assertTrue(p.undo())}
 @Test fun failedAcceptedActionStillInvalidatesOldReviewWithoutAddingHistory(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val review=capture(a);try{perform(a){error("operation refused")};fail("accepted failure") }catch(e:java.lang.reflect.InvocationTargetException){assertEquals("operation refused",e.cause?.message)};assertSame(before,p.segments);assertFalse(p.canUndo);assertEquals(1L,get(a,"captionReviewGeneration"));assertEquals(false,call(a,"canApplyCaptionReview",review))}
 @Test fun immediateUndoRestoresModelButCannotRevivePriorReview(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val review=capture(a);assertTrue(perform(a){p.setVolume(0,.5f)});assertTrue(perform(a){assertTrue(p.undo())});assertEquals(before,p.segments);assertTrue(review.state.stillMatches(call(a,"closeState")as VideoCloseState));assertEquals(false,call(a,"canApplyCaptionReview",review));assertFalse(p.canUndo);assertTrue(p.canRedo);assertEquals(2L,get(a,"captionReviewGeneration"));assertTrue(perform(a){assertTrue(p.redo())});assertEquals(.5f,p.segments[0].volume);assertEquals(3L,get(a,"captionReviewGeneration"))}
 @Test fun explicitNoOpInvalidatesPendingReviewWithoutFalseUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val review=capture(a);assertTrue(perform(a){p.setVolume(0,p.segments[0].volume)});assertSame(before,p.segments);assertFalse(p.canUndo);assertEquals(1L,get(a,"captionReviewGeneration"));assertEquals(false,call(a,"canApplyCaptionReview",review))}
 @Test fun blockedProjectPreviewReturnsBeforeNativePlayerOrWidgets(){for(flag in listOf("pause","saving","analysis","draft","import","range","bytes","blocked","checking","project","source")){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;block(a,flag);call(a,"previewProject");assertSame(before,p.segments);assertFalse(p.canUndo);assertNull(get(a,"previewPlayer"));assertEquals(0L,get(a,"captionReviewGeneration"))}}
 @Test fun blockedAudioFadeEntryCannotMutateBeforeUiRefresh(){for(flag in listOf("pause","saving","analysis","draft","import","range","bytes","blocked","checking","project","source","selection")){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;block(a,flag);call(a,"toggleAudioFade");assertSame(before,p.segments);assertFalse(p.canUndo);assertFalse(p.segments[0].audioFade);assertEquals(0L,get(a,"captionReviewGeneration"))}}
}
